* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 16px; color: #172b3a; background: #e9f0ec; }
body { min-height: 100vh; margin: 0; padding: 28px 16px; display: grid; place-items: center; background-color: #e9f0ec; background-image: radial-gradient(#cbd8d0 1px, transparent 1px); background-size: 22px 22px; }
.meter-card { width: min(100%, 460px); padding: 30px; border: 1px solid #dce5df; border-radius: 20px; background: #fffefa; box-shadow: 0 18px 48px #172b3a1c; }
.card-header { display: flex; align-items: center; gap: 14px; }
.taxi-icon { width: 46px; height: 46px; display: grid; place-items: center; border-radius: 14px; color: #172b3a; background: #f2bd58; font-size: 25px; }
.eyebrow, .panel-label, .section-label { margin: 0; font-size: 0.75rem; font-weight: 750; letter-spacing: 0.11em; }
.eyebrow { color: #61746f; }
h1 { margin: 4px 0 0; font-size: 1.3rem; line-height: 1.2; letter-spacing: -0.03em; }
.live-indicator { margin-left: auto; display: inline-flex; align-items: center; gap: 7px; color: #42725e; font-size: 0.7rem; font-weight: 800; letter-spacing: 0.09em; }
.live-indicator span { width: 8px; height: 8px; border-radius: 50%; background: #5b9b7a; box-shadow: 0 0 0 3px #5b9b7a22; }
.fare-panel { margin-top: 27px; padding: 22px 24px 19px; border-radius: 15px; color: #fffefa; background: #172b3a; }
.panel-label { color: #b9c9c7; }
.fare { margin: 8px 0 2px; color: #f2bd58; font-size: clamp(3.3rem, 15vw, 4.1rem); font-weight: 760; line-height: 1; letter-spacing: -0.065em; font-variant-numeric: tabular-nums; }
.currency { margin-right: 4px; font-size: 0.56em; vertical-align: 0.16em; }
.base-note { margin: 9px 0 0; color: #bdc9c8; font-size: 0.85rem; }
.trip-stats { display: flex; align-items: center; justify-content: space-around; padding: 22px 4px 20px; border-bottom: 1px solid #e6eae5; }
.stat { display: grid; grid-template-columns: 25px auto; column-gap: 8px; align-items: center; }
.stat-icon { grid-row: span 2; width: 25px; height: 25px; display: grid; place-items: center; border-radius: 8px; color: #42725e; background: #e9f0ec; font-size: 1.1rem; font-weight: 700; }
.clock-icon { font-size: 1.3rem; }
.stat-label { color: #71817b; font-size: 0.68rem; font-weight: 750; letter-spacing: 0.08em; }
.stat-value { margin-top: 2px; font-size: 1.25rem; font-weight: 750; font-variant-numeric: tabular-nums; }
.stat-value small { color: #71817b; font-size: 0.8rem; font-weight: 550; }
.stat-divider { width: 1px; height: 38px; background: #e6eae5; }
.controls { padding-top: 20px; }
.section-label { margin-bottom: 12px; color: #61746f; }
.button-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.add-button { min-height: 68px; padding: 11px 12px; display: flex; align-items: center; gap: 10px; border: 1px solid #dce5df; border-radius: 12px; color: #172b3a; background: #fffefa; text-align: left; font: inherit; cursor: pointer; transition: background-color 120ms, border-color 120ms, transform 120ms, box-shadow 120ms; }
.add-button:hover { border-color: #9ab7a8; background: #f4f8f4; }
.add-button:active { transform: translateY(1px); background: #e9f0ec; }
.button-symbol { width: 30px; height: 30px; flex: 0 0 30px; display: grid; place-items: center; border-radius: 9px; color: #172b3a; background: #f2bd58; font-size: 1.25rem; font-weight: 650; }
.add-button strong, .add-button small { display: block; }
.add-button strong { font-size: 0.9rem; white-space: nowrap; }
.add-button small { margin-top: 3px; color: #71817b; font-size: 0.78rem; }
button:focus-visible { outline: 3px solid #42725e; outline-offset: 3px; }
.reset-button { width: 100%; min-height: 48px; margin-top: 14px; border: 0; border-radius: 11px; color: #365d4e; background: #e9f0ec; font: inherit; font-weight: 700; cursor: pointer; transition: background-color 120ms, transform 120ms; }
.reset-button span { margin-right: 6px; font-size: 1.2rem; vertical-align: -0.04em; }
.reset-button:hover { background: #dbe8df; }
.reset-button:active { transform: translateY(1px); background: #ceded3; }
.meter-card footer { margin-top: 20px; color: #8a9891; text-align: center; font-size: 0.66rem; font-weight: 750; letter-spacing: 0.16em; }
@media (max-width: 390px) { .meter-card { padding: 24px 19px; } .button-row { grid-template-columns: 1fr; } .add-button { min-height: 60px; } }

const fareOutput = document.getElementById('fare');
const distanceOutput = document.getElementById('distance');
const waitingOutput = document.getElementById('waiting');
const addKmButton = document.getElementById('add-km');
const addMinuteButton = document.getElementById('add-minute');
const newTripButton = document.getElementById('new-trip');

let distance = 0;
let waiting = 0;

function render() {
  const fare = 3 + distance * 1.5 + waiting * 0.4;
  fareOutput.textContent = fare.toFixed(2);
  distanceOutput.textContent = String(distance);
  waitingOutput.textContent = String(waiting);
}

addKmButton.addEventListener('click', () => {
  distance += 1;
  render();
});

addMinuteButton.addEventListener('click', () => {
  waiting += 1;
  render();
});

newTripButton.addEventListener('click', () => {
  distance = 0;
  waiting = 0;
  render();
});

render();
